import math, random, importlib.util, sys
spec = importlib.util.spec_from_file_location("sched", "/app/sched.py")
sched = importlib.util.module_from_spec(spec); spec.loader.exec_module(sched)

class Env:
    def __init__(self, seed):
        rng = random.Random(seed)
        self.n_segments=40; self.b_min=4; self.b_max=8192
        self.t_overhead=1.0194; self.throughput=576.3
        self.switch = rng.randint(16,32)
        self.Bpost0 = 240*(1+rng.uniform(-0.85,0.85))
        self.growth = 8*(1+rng.uniform(-0.85,0.85))  # B per segment after switch
        self.rng=rng; self.i=0; self.t=0.0; self.calls=0
    def B(self,i):
        if i < self.switch: return 47.0
        return self.Bpost0 + self.growth*(i-self.switch)
    def steps(self,i,b):
        return 0.0258*(1+self.B(i)/b)*math.exp(self.rng.gauss(0,0.06))
    def run_segment(self,b):
        assert self.b_min<=b<=self.b_max, b
        assert self.i<40
        s=self.steps(self.i,b); t=s*(self.t_overhead+b/self.throughput)
        self.t+=t; self.i+=1; self.calls+=1
        return {"segment":self.i-1,"batch":b,"steps":s,"seconds":t,"segments_left":40-self.i,"done":self.i==40}
    def elapsed(self): return self.t

def const_time(seed,b):
    e=Env(seed)
    for _ in range(40): e.run_segment(b)
    return e.t
def oracle(seed):
    e=Env(seed); 
    for i in range(40):
        b=int(round(math.sqrt(e.B(i)*e.t_overhead*e.throughput))); e.run_segment(b)
    return e.t

tot=[];
for seed in range(200):
    e=Env(seed); sched.run(e); assert e.calls==40
    best=min(const_time(seed,b) for b in [256,320,384,448,512,640,768])
    tot.append((e.t,best,oracle(seed)))
T=sum(x[0] for x in tot)/len(tot); C=sum(x[1] for x in tot)/len(tot); O=sum(x[2] for x in tot)/len(tot)
print("sched %.3f  best-const %.3f  oracle %.3f  s_vs_oracle %.3f"%(T,C,O,(C-T)/(C-O)))
