import json, numpy as np
rows=[]
for line in open('/app/lab_log.jsonl'):
    d=json.loads(line)
    if d['op']!='profile': continue
    for s in d['result']['segments']:
        rows.append((d['result']['call_id'], s['segment'], s['batch'], s['steps'], s['seconds']))
rows=np.array(rows)
cid,k,b,s,t=rows.T
# per-step time
A=np.c_[np.ones_like(b), b]; y=t/s
t0,inv=np.linalg.lstsq(A,y,rcond=None)[0]; print("t0=%.4f thr=%.1f"%(t0,1/inv))
# pre-switch: dev switch ~ seg 25 -> use k<=24
pre=k<=24
def fit(mask, growth=False):
    kk,bb,ss=k[mask],b[mask],s[mask]
    best=None
    for S0 in np.linspace(0.020,0.032,61):
      for B0 in np.linspace(10,400,79):
        for g in ([0.0] if not growth else np.linspace(-0.1,0.3,41)):
          k0 = kk.min()
          pred=S0*(1+B0*(1+g*(kk-k0))/bb)
          r=np.log(ss/pred); e=(r**2).sum()
          if best is None or e<best[0]: best=(e,S0,B0,g)
    return best
print("pre  S,B,g:",fit(pre,True))
print("pre  S,B  :",fit(pre,False))
post=k>=25
print("post S,B,g:",fit(post,True))
print("post S,B  :",fit(post,False))
# post with S fixed at pre S
e,S0,B0,g=fit(pre,False)
kk,bb,ss=k[post],b[post],s[post]
Best=None
for Bp in np.linspace(50,600,111):
  for gg in np.linspace(-0.1,0.4,51):
    pred=S0*(1+Bp*(1+gg*(kk-25))/bb); r=np.log(ss/pred); e=(r**2).sum()
    if Best is None or e<Best[0]: Best=(e,Bp,gg)
print("post S fixed:",S0,Best)
# residual noise pre
pred=S0*(1+B0/b[pre]); print("pre resid sd %.3f"%np.std(np.log(s[pre]/pred)))
# per-segment implied B post (S fixed)
for kk_,bb_,ss_ in sorted(zip(k[post],b[post],s[post])):
    print(int(kk_),int(bb_),"B=%.0f"%(bb_*(ss_/S0-1)))

